        let arr = d.entries || d || [];
        this.states[k] = arr;
        let mx = 0;
        for (let i = 0; i < arr.length; i++) if (arr[i].seq > mx) mx = arr[i].seq;
        this.seqs[k] = mx;
        this.save(k);
        this.refresh(k);
